// src/lib/mcp/tools/cash-summary.ts
import { createClient as createClient6 } from "npm:@supabase/supabase-js@^2.97.0";
import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z5 } from "npm:zod@^3.25.76";
function db6(ctx) {
  return createClient6(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
var cash_summary_default = defineTool6({
  name: "cash_summary",
  title: "Cash summary (revenue vs expense)",
  description: "Summary of a company's revenue, expenses and net cash flow in a date range. Dates ISO YYYY-MM-DD.",
  inputSchema: {
    company_id: z5.string().uuid().describe("Company UUID."),
    from: z5.string().describe("Start date, inclusive."),
    to: z5.string().describe("End date, inclusive.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ company_id, from, to }, ctx) => {
    if (!ctx.isAuthenticated())
      return { content: [{ type: "text", text: "N\xE3o autenticado" }], isError: true };
    const { data, error } = await db6(ctx).from("transactions").select("type, amount").eq("company_id", company_id).gte("date", from).lte("date", to);
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    const rows = data ?? [];
    let revenue = 0;
    let expense = 0;
    for (const r of rows) {
      const v = Number(r.amount) || 0;
      if (r.type === "revenue") revenue += v;
      else if (r.type === "expense") expense += v;
    }
    const net = revenue - expense;
    const fmt = (n) => n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
    return {
      content: [
        {
          type: "text",
          text: `Per\xEDodo ${from} \u2192 ${to}
Receitas: ${fmt(revenue)}
Despesas: ${fmt(expense)}
Resultado l\xEDquido: ${fmt(net)}
(${rows.length} lan\xE7amentos)`
        }
      ],
      structuredContent: { revenue, expense, net, count: rows.length, from, to }
    };
  }
});

